svg.script:
(() => {
  const svg = document.documentElement;
  const baseSeconds = 1.371;
  const frames = [...svg.querySelectorAll('animate[attributeName="opacity"]')];
  const setSpinSpeed = speed => {
    speed = Number(speed);
    if (!Number.isFinite(speed) || speed <= 0) return;
    svg.dataset.speed = String(speed);
    const cycleSeconds = baseSeconds / speed;
    frames.forEach(frame => {
      frame.setAttribute('dur', `${cycleSeconds}s`);
    });
    svg.setCurrentTime?.(0);
  };
  window.setSpinSpeed = setSpinSpeed;
  setSpinSpeed(svg.dataset.speed);
})();
